message:
can you review this for soundness? sharing a raw pointer across threads, feels sketchy

```rust
struct Shared(*mut Vec<u8>);
unsafe impl Send for Shared {}
unsafe impl Sync for Shared {}

fn fill(buf: &mut Vec<u8>) {
    let s = std::sync::Arc::new(Shared(buf as *mut _));
    let mut hs = vec![];
    for t in 0..4 {
        let s = s.clone();
        hs.push(std::thread::spawn(move || unsafe {
            let v = &mut *s.0;
            if t == 0 { v.push(0); }
            for i in (t..v.len()).step_by(4) { v[i] = t as u8; }
        }));
    }
    for h in hs { h.join().unwrap(); }
}
